import { h } from "./h.js";

const TEXT = {
  pass: {
    title: "Reference image signature verified",
    icon: "✓",
    blurb: "The embedded processed image carries a valid Apple signature.",
  },
  fail: {
    title: "Signature check failed",
    icon: "✗",
    blurb:
      "The file carries a Reference Image signature, but it does not verify.",
  },
  "not-reference-image": {
    title: "Not a Reference Image",
    icon: "○",
    blurb: "This photo has no Apple provenance data to verify.",
  },
  error: { title: "Could not analyse this file", icon: "!", blurb: "" },
};

function statusIcon(ok, seal = false) {
  return h(
    "svg",
    {
      viewBox: "0 0 48 48",
      fill: "none",
      "aria-hidden": "true",
      focusable: "false",
      stroke: "currentColor",
      "stroke-width": 2.5,
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
    },
    seal &&
      h("circle", { cx: 24, cy: 24, r: 21, "stroke-width": 1, opacity: 0.3 }),
    seal && h("circle", { cx: 24, cy: 24, r: 17, "stroke-width": 1.2 }),
    h("path", { d: ok ? "M15 24l6 6 12-13" : "M17 17l14 14M31 17L17 31" }),
  );
}

export function renderVerdict(report) {
  const v = report.verdict;
  const t = TEXT[v.status] || TEXT.error;
  return h(
    `section.verdict.verdict-${v.status}`,
    { "aria-live": "polite" },
    h(
      "div.verdict-head",
      h(
        "span.verdict-icon",
        v.status === "pass" ? statusIcon(true, true) : t.icon,
      ),
      h("div", h("h2", t.title), h("p.verdict-blurb", t.blurb)),
    ),
    h(
      "div.verdict-reasons",
      v.reasons.map((r) => h("p", r)),
    ),
  );
}
