// P, S, C → CombinedHash → M' → ML-DSA-87 ‖ RSA-3072-PSS
import { h, hexCell, check, partTag, fmtRange } from "./h.js";

export function renderHashTree(report, opts = {}) {
  const hz = report.hashing,
    sig = report.signature;
  const step = opts.step ?? 3;
  const leaf = (part, name, hex, range, note) =>
    h(
      `div.ht-node.ht-leaf.part-${part}`,
      h("div.ht-title", partTag(part), ` ${name}`),
      h(
        "div.ht-sub",
        `SHA-512 of ${fmtRange(...range)}${note ? " " + note : ""}`,
      ),
      hexCell(hex, 8),
    );
  return h(
    "div.hashtree",
    h(
      "div.ht-row.ht-leaves",
      leaf("P", "PreambleHash", hz.preambleHash, hz.ranges.preamble),
      leaf(
        "S",
        "SignatureParametersHash",
        hz.signatureParametersHash,
        hz.ranges.signatureParameters,
        `minus ${fmtRange(...hz.ranges.excluded)}`,
      ),
      leaf("C", "ContentHash", hz.contentHash, hz.ranges.content),
    ),
    arrow(`SHA-512( ${hz.order} )`),
    h(
      "div.ht-row",
      h(
        "div.ht-node.ht-combined",
        h("div.ht-title", "CombinedHash"),
        h("div.ht-sub", "64 B"),
        hexCell(hz.combinedHash, 12),
      ),
    ),
    step >= 2 && arrow("composite pre-hash wrapping (IETF LAMPS)"),
    step >= 2 &&
      h(
        "div.ht-row",
        h(
          "div.ht-node.ht-mprime",
          h("div.ht-title", "M′"),
          h("div.ht-sub", "131 B"),
          h(
            "div.mprime",
            grp("Prefix", `"${hz.mPrime.prefix}"`, "32 B"),
            grp("Label", `"${hz.mPrime.label}"`, "34 B"),
            grp("ctx len", "0x00", "1 B"),
            grp("CombinedHash", hexCell(hz.mPrime.digest, 8), "64 B"),
          ),
        ),
      ),
    step >= 3 &&
      sig &&
      arrow(
        "both halves sign exactly M′ (empty context; the label separates domains), verified with the signer certificate's key",
      ),
    step >= 3 &&
      sig &&
      h(
        "div.ht-row.ht-sigs",
        sigNode(
          "ML-DSA-87",
          "FIPS 204, pure mode, ctx = label",
          `${sig.mldsa.length} B`,
          sig.mldsa.valid,
        ),
        h("div.ht-plus", "‖"),
        sigNode(
          "RSA-3072 PSS",
          "SHA-256, MGF1-SHA-256, salt 32",
          `${sig.rsa.length} B`,
          sig.rsa.valid,
        ),
      ),
    step >= 3 &&
      sig &&
      h(
        "p.ht-rule",
        sig.valid
          ? "Both halves verify, so the composite signature is valid."
          : "A composite signature is valid only if both halves verify. Here it is not.",
      ),
  );
}

const arrow = (label) =>
  h("div.ht-arrow", h("span", "↓"), label && h("small", label));
const grp = (name, value, size) =>
  h(
    "div.mp-grp",
    h("small", name),
    h("div.mp-val", value),
    h("small.mp-size", size),
  );
const sigNode = (name, sub, size, ok) =>
  h(
    `div.ht-node.ht-sig.${ok ? "ok" : "bad"}`,
    h("div.ht-title", check(ok), ` ${name}`),
    h("div.ht-sub", `${sub} · ${size}`),
  );
