// Tiny DOM/SVG builder: h("div.cls#id", {attr: v, onclick: fn}, ...children).
const SVG_NS = "http://www.w3.org/2000/svg";
const SVG_TAGS = new Set([
  "svg",
  "g",
  "rect",
  "path",
  "line",
  "text",
  "circle",
  "defs",
  "pattern",
  "title",
  "polyline",
  "tspan",
]);

export function h(spec, attrs, ...children) {
  if (
    attrs &&
    (typeof attrs !== "object" || attrs instanceof Node || Array.isArray(attrs))
  ) {
    children.unshift(attrs);
    attrs = null;
  }
  const [tag, ...mods] = spec.split(/(?=[.#])/);
  const el = SVG_TAGS.has(tag)
    ? document.createElementNS(SVG_NS, tag)
    : document.createElement(tag);
  for (const m of mods)
    m[0] === "." ? el.classList.add(m.slice(1)) : (el.id = m.slice(1));
  if (attrs) {
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k.startsWith("on") && typeof v === "function")
        el.addEventListener(k.slice(2), v);
      else if (k === "class") el.setAttribute("class", v);
      else if (k === "dataset") Object.assign(el.dataset, v);
      else if (k === "style" && typeof v === "object")
        Object.assign(el.style, v);
      else el.setAttribute(k, v === true ? "" : v);
    }
  }
  append(el, children);
  return el;
}

function append(el, children) {
  for (const c of children) {
    if (c == null || c === false) continue;
    if (Array.isArray(c)) append(el, c);
    else el.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
}

export const frag = (...children) => {
  const f = document.createDocumentFragment();
  append(f, children);
  return f;
};

export function fmtBytes(n) {
  if (n == null) return "—";
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(2)} MB`;
}
export const fmtInt = (n) => (n == null ? "—" : n.toLocaleString("en-US"));
export const fmtRange = (a, b) => `[${fmtInt(a)}, ${fmtInt(b)})`;
export const shortHex = (hex, n = 8) =>
  hex ? `${hex.slice(0, n)}…${hex.slice(-n)}` : "—";
export function fmtDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  return (
    d.toLocaleString("en-GB", {
      dateStyle: "medium",
      timeStyle: "medium",
      timeZone: "UTC",
    }) + " UTC"
  );
}

export function copyButton(text, label = "copy") {
  const btn = h("button.copy", { type: "button", title: `Copy ${label}` }, "⧉");
  btn.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(text);
      btn.textContent = "✓";
      setTimeout(() => (btn.textContent = "⧉"), 1200);
    } catch {
      btn.textContent = "✗";
    }
  });
  return btn;
}

export const hexCell = (hex, n = 12) =>
  h("span.hex", { title: hex }, h("code", shortHex(hex, n)), copyButton(hex));
export const check = (ok) =>
  h(
    `span.mark.${ok ? "ok" : "bad"}`,
    { "aria-label": ok ? "valid" : "invalid" },
    ok ? "✓" : "✗",
  );
export const partTag = (part) => h(`span.part.part-${part}`, part);
