// The analysis pipeline shared by the standalone page and the blog embed:
// reject obvious non-photos early, then run the verifier. Nothing leaves the
// browser.
import { verifyReferenceImage, isJpeg, isHeif } from "reference-image";

// Sniff the container from the first bytes so a PDF, PNG or video is rejected
// before the whole file is read, with a message that names what it was.
const SNIFF = [
  ["%PDF", "a PDF document"],
  ["\x89PNG", "a PNG image"],
  ["GIF8", "a GIF image"],
  ["RIFF", "a WebP image or RIFF media file"],
  ["II*\0", "a TIFF or raw image"],
  ["MM\0*", "a TIFF or raw image"],
  ["PK\x03\x04", "a ZIP archive"],
];

export async function sniffUnsupported(file) {
  const head = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  if (isJpeg(head) || isHeif(head)) return null;
  const ascii = String.fromCharCode(...head);
  const hit = SNIFF.find(([magic]) => ascii.startsWith(magic));
  const what = hit
    ? hit[1]
    : /^(image|video)\//.test(file.type)
      ? `a ${file.type} file`
      : "not a recognised image";
  return `${file.name} is ${what}. This tool needs a JPEG or HEIC/HEIF photo straight from an iPhone.`;
}

// Verify a File. `onStep(label)` is called before each slow phase so the
// caller can show progress. Resolves to { report, processedJpeg, ms }.
export async function analyse(file, onStep = () => {}) {
  onStep("Reading");
  const unsupported = await sniffUnsupported(file);
  if (unsupported) return { report: errorReport(file, unsupported) };
  const bytes = new Uint8Array(await file.arrayBuffer());
  onStep("Checking");
  await new Promise((r) => setTimeout(r, 20)); // let the status paint
  const t0 = performance.now();
  const { report, processedJpeg } = await verifyReferenceImage(bytes, {
    fileName: file.name,
  });
  return { report, processedJpeg, ms: Math.round(performance.now() - t0) };
}

export function errorReport(file, message) {
  return {
    verdict: { status: "error", reasons: [message] },
    file: { name: file.name },
    certificates: [],
  };
}

// Load a photo from a URL (the bundled example) as a File.
export async function fetchPhoto(url, name) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(res.statusText);
  return new File([await res.blob()], name, { type: "image/jpeg" });
}
