// The photo next to the reference image it carries, with a click-to-compare
// viewer. Used by the standalone page and the blog embed; the viewer's dialog
// is created inside the returned element so it works in a shadow root too.
import { h } from "./h.js";

const LABELS = ["User-facing Image", "Reference image"];

// Can the browser paint this URL natively? (HEIC: Safari yes, others no.)
export function canDecode(url) {
  const img = new Image();
  img.src = url;
  return img.decode().then(
    () => true,
    () => false,
  );
}

// A URL the browser can show for the uploaded file. HEIC is converted to JPEG
// with libheif (heic-to) only when native decoding fails, so the 3 MB decoder
// is never fetched in Safari or for JPEG uploads. `track` is called with every
// object URL created so the caller can revoke them later; `isCurrent` lets a
// slow conversion bail out when a newer file has replaced this one.
export async function displayableUrl(file, track, isCurrent = () => true) {
  const native = track(URL.createObjectURL(file));
  if (await canDecode(native)) return native;
  const { heicTo } = await import("heic-to/csp");
  const jpeg = await heicTo({ blob: file, type: "image/jpeg", quality: 0.92 });
  if (!isCurrent()) throw new Error("superseded");
  return track(URL.createObjectURL(jpeg));
}

// `outer` is a URL (or a promise of one) for the photo; `inner` a URL for the
// embedded reference image, or null when the file carries none. Keep both
// full-size images loaded so switching does not wait for decoding.
export function renderMedia({ outer, inner, certified = false }) {
  const notes = [
    "Unverified",
    certified ? "Cryptographically Certified" : "Unverified",
  ];
  const figure = (src, index, caption = true) => {
    const slot = h("div.noimg", "Decoding…");
    const fig = h(
      "figure",
      slot,
      caption &&
        h("figcaption", h("strong", LABELS[index]), h("span", notes[index])),
    );
    Promise.resolve(src).then(
      (url) =>
        slot.replaceWith(
          h("img", { src: url, alt: LABELS[index], draggable: "false" }),
        ),
      () => (slot.textContent = "Browser can't show this image"),
    );
    return fig;
  };

  // The viewer: the image fills the dialog and the controls float over it,
  // iOS-style. A pill at the bottom switches images, and a hint asks for a
  // click until the first flip.
  const compareContent = h("div.compare-frame");
  const compare = h(
    "dialog.compare",
    { "aria-label": "Compare user-facing and reference images" },
    compareContent,
  );
  compare.addEventListener("click", (e) => {
    if (e.target === compare) compare.close();
  });

  const openCompare = (initial = 0) => {
    const images = [figure(outer, 0, false), figure(inner, 1, false)];
    let selected = initial;
    let flipped = false;
    const touch = matchMedia("(hover: none)").matches;
    const hint = h(
      "div.compare-hint",
      `${touch ? "Tap" : "Click"} the image to compare`,
    );
    const dismissHint = () => hint.setAttribute("data-hidden", "");
    const show = (index) => {
      images.forEach((image, i) => {
        image.hidden = i !== index;
      });
      buttons.forEach((button, i) =>
        button.setAttribute("aria-pressed", String(i === index)),
      );
      stage.setAttribute(
        "aria-label",
        `Showing ${LABELS[index].toLowerCase()}. ${touch ? "Tap" : "Click"} to show ${LABELS[1 - index].toLowerCase()}.`,
      );
    };
    const flip = () => {
      selected = 1 - selected;
      flipped = true;
      dismissHint();
      show(selected);
    };
    const buttons = LABELS.map((label, index) =>
      h(
        "button",
        {
          type: "button",
          onclick: () => {
            selected = index;
            show(selected);
          },
        },
        label,
      ),
    );
    const stage = h(
      "div.compare-stage",
      {
        role: "button",
        tabindex: "0",
        onkeydown: (e) => {
          if (e.key !== " " && e.key !== "Enter") return;
          e.preventDefault();
          flip();
        },
        onclick: flip,
      },
      ...images,
    );
    compareContent.replaceChildren(
      stage,
      h(
        "button.compare-close",
        {
          type: "button",
          "aria-label": "Close",
          onclick: () => compare.close(),
        },
        h(
          "svg",
          {
            viewBox: "0 0 24 24",
            width: 16,
            height: 16,
            fill: "none",
            stroke: "currentColor",
            "stroke-width": 2.6,
            "stroke-linecap": "round",
            "aria-hidden": "true",
            focusable: "false",
          },
          h("path", { d: "M6 6l12 12M18 6L6 18" }),
        ),
      ),
      h(
        "div.compare-hud",
        hint,
        h(
          "div.compare-switch",
          { role: "group", "aria-label": "Displayed image" },
          ...buttons,
        ),
      ),
    );
    show(selected);
    compare.showModal();
    setTimeout(() => {
      if (!flipped) dismissHint();
    }, 4000);
  };

  const thumbs = [outer, inner].filter(Boolean).map((url, index) => {
    const fig = figure(url, index);
    if (inner) {
      const image = fig.firstChild;
      const button = h("button.preview-open", {
        type: "button",
        "aria-label": `View ${LABELS[index].toLowerCase()} full size`,
        onclick: () => openCompare(index),
      });
      image.replaceWith(button);
      button.append(image);
    }
    return fig;
  });
  return h(
    "div.verdict-media",
    h("div.drop-images", ...thumbs),
    inner &&
      h(
        "button.btn.small",
        { type: "button", onclick: () => openCompare() },
        "Compare full size",
      ),
    compare,
  );
}
