// Anatomy of the signature box (JUMBF box 3) and the timestamps in box 2.
import { h, fmtBytes, fmtInt, fmtRange, fmtDate, partTag } from "./h.js";

export function renderBoxAnatomy(report) {
  const s = report.boxes.signature,
    sig = report.signature;
  const segEnd = s.offset + s.length;
  const rows = [
    ["APP11 marker + segment length", s.offset, s.offset + 4, "S"],
    ['"JP" + instance + sequence', s.offset + 4, s.offset + 12, "S"],
    [`outer uuid box ${s.uuid}`, s.offset + 12, s.innerOffset, "S"],
    [
      `inner uuid box ${s.innerUuid} header`,
      s.innerOffset,
      s.innerOffset + 24,
      "S",
    ],
    ["reserved (zero)", s.innerOffset + 24, s.sigLenOffset, "S"],
    ["u32 signature length", s.sigLenOffset, s.sigDerOffset, "X"],
    [
      `signature DER: SEQUENCE { version ${sig?.structureVersion ?? "?"}, OCTET STRING(${sig?.length ?? "?"}) } = ML-DSA-87 (${sig?.mldsa.length}) ‖ RSA (${sig?.rsa.length})`,
      s.sigDerOffset,
      s.sigDerOffset + s.sigDerLength,
      "X",
    ],
    ["u32 bundle length", s.bundleLenOffset, s.bundleOffset, "S"],
    [
      `certificate bundle DER: version ${sig?.bundleVersion ?? "?"}, ${sig?.algorithm ?? "?"}, ${report.certificates.filter((c) => c.embeddedInFile).length} certificates`,
      s.bundleOffset,
      s.trailerOffset,
      "S",
    ],
    [
      `trailer: u16 version + u64 development time (${s.trailerHex}) → ${fmtDate(s.developedAt)}`,
      s.trailerOffset,
      segEnd,
      "S",
    ],
  ];
  return h(
    "div.anatomy",
    h(
      "table.anatomy-table",
      h(
        "thead",
        h(
          "tr",
          h("th", "Field"),
          h("th.num", "Range"),
          h("th.num", "Bytes"),
          h("th", "Hashed?"),
        ),
      ),
      h(
        "tbody",
        rows.map(([name, a, b, part]) =>
          h(
            `tr.row-${part}`,
            h("td", name),
            h("td.num", fmtRange(a, b)),
            h("td.num", fmtInt(b - a)),
            h(
              "td",
              part === "X"
                ? h("span.part.part-X", "✂ excluded")
                : h("span.part.part-S", "S"),
            ),
          ),
        ),
      ),
    ),
    h(
      "p.muted",
      "Excluded bytes are skipped, not zeroed: the remaining bytes of the segment are concatenated and hashed. Everything else in the box, including the certificates and the development time, is bound by the signature.",
    ),
  );
}

export function renderTimestamps(report) {
  const t = report.boxes.timestamps,
    dev = report.boxes.signature.developedAt;
  if (!t) return h("p.muted", "No timestamp box found.");
  const cap = report.file.exif?.dateTimeOriginal;
  const names = [
    "Timestamp 1 (earliest; a pre-issued token?)",
    "Timestamp 2",
    "Timestamp 3",
  ];
  const base = t.unix[1];
  return h(
    "div",
    h(
      "table.ts-table",
      h(
        "thead",
        h(
          "tr",
          h("th", "#"),
          h("th", "Hashed in"),
          h("th", "Unix time"),
          h("th", "UTC"),
          h("th", "Δ vs. second"),
          h("th", "Reading"),
        ),
      ),
      h(
        "tbody",
        t.unix.map((u, i) =>
          h(
            "tr.row-P",
            h("td", i + 1),
            h("td", partTag("P"), " box 2"),
            h("td.num", u),
            h("td", fmtDate(t.iso[i])),
            h("td.num", delta(u - base)),
            h("td", names[i] || ""),
          ),
        ),
        h(
          "tr.row-S",
          h("td", "trailer"),
          h("td", partTag("S"), " box 3"),
          h("td.num", report.boxes.signature.developedAtUnix),
          h("td", fmtDate(dev)),
          h("td.num", delta(report.boxes.signature.developedAtUnix - base)),
          h("td", "Development time, inside the signed trailer"),
        ),
      ),
    ),
    h(
      "p.muted",
      `Box 2 lies in the preamble (P) and the trailer in the signature-parameters range (S), so all four values are signed. ${cap ? `The outer Exif DateTimeOriginal says ${cap} (local time, unsigned).` : ""} Apple does not document what the three values mean; in the samples seen so far the first precedes the others by minutes and the last equals the development time in the trailer.`,
    ),
  );
}

const delta = (s) =>
  s === 0
    ? "0 s"
    : `${s > 0 ? "+" : "−"}${Math.abs(s) >= 120 ? `${Math.round(Math.abs(s) / 60)} min` : `${Math.abs(s)} s`}`;
