import { h, check, fmtDate, hexCell } from "./h.js";

const ROLE = {
  signer: "Signer (leaf)",
  "issuing-ca": "Issuing CA",
  "intermediate-ca": "Intermediate CA",
  root: "Root CA (trust anchor)",
};

export function renderCertChain(report) {
  const certs = report.certificates;
  return h(
    "div.chain",
    certs.map((c, i) => [
      i > 0 &&
        h(
          "div.chain-arrow",
          h("span", "↑"),
          h("small", "issued and signed by"),
        ),
      h(
        `details.cert.cert-${c.role}.${c.signature.valid && c.withinValidity ? "ok" : "bad"}`,
        h(
          "summary",
          h(
            "div.cert-head",
            h("span.cert-role", ROLE[c.role] || c.role),
            check(c.signature.valid && c.withinValidity),
          ),
          h("h4", c.subjectCN || c.subject),
        ),
        h(
          "dl",
          dt("Issuer", c.issuerCN),
          dt("Serial", h("code", c.serial)),
          dt(
            "Valid",
            `${fmtDate(c.notBefore).slice(0, 11)} → ${fmtDate(c.notAfter).slice(0, 11)}${c.withinValidity ? "" : " (outside validity!)"}`,
          ),
          dt("Algorithm", c.algorithm),
          dt("SHA-256", hexCell(c.sha256, 8)),
          dt(
            "Signature",
            h(
              "span",
              check(c.signature.mldsa),
              " ML-DSA ",
              check(c.signature.rsa),
              " RSA",
              c.verifiedBy ? h("small", ` (key of ${c.verifiedBy})`) : null,
            ),
          ),
          dt(
            "Where from",
            c.embeddedInFile
              ? "embedded in the photo"
              : "built into the verifier (Apple does not publish it)",
          ),
        ),
        c.role === "signer" &&
          h(
            "p.muted",
            "Apple's Reference image development service certificate.",
          ),
      ),
    ]),
    report.chain?.errors.length
      ? h(
          "ul.chain-errors",
          report.chain.errors.map((e) => h("li", e)),
        )
      : null,
  );
}
const dt = (k, v) => [h("dt", k), h("dd", v)];
