// "Where the signed image hides": nested boxes from the outer photo down to
// the signature.
import { h, fmtBytes, fmtInt } from "./h.js";

export function renderFileMap(report) {
  const f = report.file,
    c = report.carrier,
    p = report.processed,
    b = report.boxes;
  const outerLabel = f.container === "heif" ? "HEIC container" : "JPEG file";
  const outerFacts = [
    f.width && `${f.width} × ${f.height} px`,
    fmtBytes(f.size),
    ...formatFacts(f.format),
    f.exif?.model,
    f.exif?.appleReferenceFlag != null &&
      `MakerNote 0x0063 = ${f.exif.appleReferenceFlag}${f.exif.appleReferenceFlag === 8 ? " (developed Reference Image)" : ""}`,
  ];
  const carrierLabel =
    c.kind === "heif-item"
      ? `Item #${c.itemId} of type "uri "`
      : `${c.chunkCount} APP3 segments`;
  const carrierFacts =
    c.kind === "heif-item"
      ? [
          `tag:apple.com,2025:photo:metadata:provenance:processedimage`,
          `at offset ${fmtInt(c.itemOffset)}, ${fmtBytes(c.itemLength)}`,
          c.describesPrimary
            ? "linked to the primary image (cdsc)"
            : "not linked to the primary image",
        ]
      : [
          `id tag:apple.com,2025:chunked_binary_metadata:…provenance:processedimage`,
          `${fmtBytes(c.carrierBytes)} in total, 4-byte seq/total header per chunk`,
        ];
  return h(
    "div.filemap",
    box(
      "outer",
      outerLabel,
      "The user-facing image, not cryptographically certified",
      outerFacts,
      box(
        "carrier",
        carrierLabel,
        null,
        carrierFacts,
        box(
          "processed",
          "Reference image (JPEG)",
          "This is the cryptographically certified part.",
          [
            `${p.width} × ${p.height} px`,
            fmtBytes(p.size),
            ...formatFacts(p.format),
            `${p.segments.length} segments`,
          ],
          h(
            "div.filemap-row",
            box("box box-P", "JUMBF box 1", "Header", [
              `spec ${b.header?.specVersion ?? "?"}`,
              `${b.header?.length ?? "?"} B`,
            ]),
            box("box box-P", "JUMBF box 2", "Timestamps", [
              `${b.timestamps?.unix.length ?? 0} × u64`,
              `${b.timestamps?.length ?? "?"} B`,
            ]),
            box(
              "box box-S",
              "JUMBF box 3",
              "Signature box",
              [fmtBytes(b.signature.length)],
              h(
                "div.filemap-row",
                box("leaf leaf-sig", "Signature", "excluded from the hash", [
                  `${report.signature?.length ?? "?"} B`,
                  "ML-DSA-87 ‖ RSA",
                ]),
                box("leaf", "Certificates", "signed", [
                  `${report.certificates.filter((x) => x.embeddedInFile).length} certs`,
                  fmtBytes(b.signature.bundleLength),
                ]),
                box("leaf", "Trailer", "signed", [
                  `${b.signature.trailerLength} B`,
                  "development time",
                ]),
              ),
            ),
          ),
          box("box box-C", "Pixel data", "SOF, tables, scan", [
            fmtBytes(p.segments.find((s) => s.name === "scan")?.length),
          ]),
        ),
      ),
    ),
  );
}

// "JPEG baseline DCT, Huffman (ISO/IEC 10918-1) · 8-bit YCbCr 4:2:0 · JFIF 1.01, Exif 2.32"
function formatFacts(fmt) {
  if (!fmt) return [];
  const versions = [
    fmt.jfifVersion && `JFIF ${fmt.jfifVersion}`,
    fmt.exifVersion && `Exif ${fmt.exifVersion}`,
  ].filter(Boolean);
  return [
    fmt.process &&
      `JPEG ${fmt.process[0].toLowerCase()}${fmt.process.slice(1)} (ISO/IEC 10918-1)`,
    fmt.precision &&
      `${fmt.precision}-bit${fmt.components === 3 ? " YCbCr" : fmt.components ? ` ${fmt.components} comp.` : ""}${fmt.subsampling ? ` ${fmt.subsampling}` : ""}`,
    versions.length && versions.join(", "),
  ];
}

function box(cls, title, sub, facts, ...children) {
  return h(
    `div.fm.fm-${cls.split(" ").join(".fm-")}`,
    h("div.fm-head", h("strong", title), sub && h("span.fm-sub", sub)),
    facts &&
      h(
        "ul.fm-facts",
        facts.filter(Boolean).map((x) => h("li", x)),
      ),
    ...children,
  );
}
