// Byte map of the processed JPEG: which bytes feed which hash. Widths are on a
// log scale (the scan is >99% of the file); a true-scale strip sits beneath.
import { h, fmtBytes, fmtInt, fmtRange, partTag } from "./h.js";

const PART_NAME = {
  P: "Preamble hash",
  S: "Signature-parameters hash",
  C: "Content hash",
};

export function renderByteMap(report, opts = {}) {
  const p = report.processed,
    hz = report.hashing;
  const [exStart, exEnd] = hz.ranges.excluded;
  // Split the signature-box segment into signed / excluded / signed pieces.
  const pieces = [];
  for (const s of p.segments) {
    if (s.part === "S" && exStart >= s.offset && exEnd <= s.offset + s.length) {
      pieces.push({ ...s, length: exStart - s.offset, label: "box 3 head" });
      pieces.push({
        ...s,
        offset: exStart,
        length: exEnd - exStart,
        part: "X",
        name: "excluded",
        label: "u32 len + signature DER",
      });
      pieces.push({
        ...s,
        offset: exEnd,
        length: s.offset + s.length - exEnd,
        name: "APP11",
        label: "certs + trailer",
      });
    } else pieces.push({ ...s, label: s.detail });
  }
  const weight = (n) => Math.log2(Math.max(n, 2)) + 1.5;
  const total = pieces.reduce((a, s) => a + weight(s.length), 0);
  const W = 1000,
    H = 44;
  const rects = [];
  let x = 0;
  pieces.forEach((s, i) => {
    const w = (weight(s.length) / total) * W;
    rects.push(
      h(
        "g",
        { class: `bm-seg part-${s.part}`, dataset: { i } },
        h("rect", {
          x: x + 0.5,
          y: 4,
          width: Math.max(w - 1, 1),
          height: H - 8,
          rx: 3,
          class: s.part === "X" ? "hatch" : "",
        }),
        w > 46 &&
          h(
            "text",
            { x: x + w / 2, y: H / 2 + 4, "text-anchor": "middle" },
            s.name === "scan" ? "scan data" : s.name,
          ),
        h(
          "title",
          `${s.name} ${fmtRange(s.offset, s.offset + s.length)} · ${fmtBytes(s.length)} · ${s.part === "X" ? "excluded from every hash" : PART_NAME[s.part]}`,
        ),
      ),
    );
    s.x = x;
    s.w = w;
    x += w;
  });
  // True-scale strip.
  const strip = pieces.map((s) =>
    h("rect", {
      class: `part-${s.part}`,
      x: (s.offset / p.size) * W,
      y: 0,
      width: Math.max((s.length / p.size) * W, 0.75),
      height: 8,
    }),
  );
  const svg = h(
    "svg.bytemap",
    {
      viewBox: `0 0 ${W} ${H + 24}`,
      preserveAspectRatio: "none",
      role: "img",
      "aria-label": "Byte map of the processed JPEG",
    },
    h(
      "defs",
      h(
        "pattern#hatch",
        {
          width: 6,
          height: 6,
          patternUnits: "userSpaceOnUse",
          patternTransform: "rotate(45)",
        },
        h("rect", { width: 6, height: 6, class: "hatch-bg" }),
        h("rect", { width: 2, height: 6, class: "hatch-fg" }),
      ),
    ),
    rects,
    h(
      "g",
      { transform: `translate(0 ${H + 12})`, class: "bm-strip" },
      strip,
      h("title", "Same file, true scale"),
    ),
  );
  const legend = h(
    "div.bm-legend",
    ["P", "S", "C"].map((k) =>
      h(
        "span",
        partTag(k),
        ` ${PART_NAME[k]} ${fmtRange(...hz.ranges[{ P: "preamble", S: "signatureParameters", C: "content" }[k]])}`,
      ),
    ),
    h(
      "span",
      h("span.part.part-X", "✂"),
      ` excluded ${fmtRange(exStart, exEnd)}: not in any hash`,
    ),
  );
  const rows = p.segments.map((s, i) =>
    h(
      "tr",
      { dataset: { seg: i }, class: `row-${s.part}` },
      h("td.num", fmtInt(s.offset)),
      h("td", h("code", s.name)),
      h("td.num", fmtInt(s.length)),
      h("td", s.detail),
      h(
        "td",
        partTag(s.part),
        s.part === "S" && h("small", ` minus ${fmtRange(exStart, exEnd)}`),
      ),
    ),
  );
  const table = h(
    "details.bm-table",
    { open: opts.tableOpen ?? true },
    h(
      "summary",
      `Segment table (${p.segments.length} segments, ${fmtBytes(p.size)})`,
    ),
    h(
      "table",
      h(
        "thead",
        h(
          "tr",
          h("th.num", "Offset"),
          h("th", "Marker"),
          h("th.num", "Bytes"),
          h("th", "Content"),
          h("th", "Hash"),
        ),
      ),
      h("tbody", rows),
    ),
  );
  // Floating label for segments too narrow to show their name inline.
  const tip = h("div.bm-tip", { hidden: true });
  const plot = h("div.bm-plot", svg, tip);
  svg.addEventListener("mouseleave", () => (tip.hidden = true));
  // Hover sync.
  svg.addEventListener("mouseover", (e) => {
    const g = e.target.closest(".bm-seg");
    if (!g) return;
    const seg = pieces[+g.dataset.i];
    const text = g.querySelector("text");
    if (text && getComputedStyle(text).display !== "none") tip.hidden = true;
    else {
      tip.textContent = seg.name === "scan" ? "scan data" : seg.name;
      tip.style.left = `${((seg.x + seg.w / 2) / W) * 100}%`;
      tip.hidden = false;
    }
    table.querySelectorAll("tr.hl").forEach((r) => r.classList.remove("hl"));
    const idx = p.segments.findIndex(
      (s) => s.offset <= seg.offset && seg.offset < s.offset + s.length,
    );
    table.querySelector(`tr[data-seg="${idx}"]`)?.classList.add("hl");
  });
  return h(
    "div.bytemap-wrap",
    plot,
    legend,
    h(
      "p.muted",
      "Widths are on a log scale so the small header segments stay visible; the thin strip below is to scale.",
    ),
    table,
  );
}
